    ConversationFlags,
    Message,
    ToolFilter,
    cmd_parse,
    parse_jsonl as _parse_jsonl,
)
from chats.formatting import format_to_xml


CLAUDE_SOURCE_PATH = Path.home() / ".claude" / "projects" / "tests" / "session.jsonl"


def parse_jsonl(content: str, flags: ConversationFlags) -> list[Message]:
    """Parse test content through an explicit Claude session path."""
    return _parse_jsonl(content, flags, source_path=CLAUDE_SOURCE_PATH)


def _utc_to_local_display(utc_iso: str) -> str:
    """Convert a UTC ISO timestamp to the local-time display string used in date attrs."""
    dt = datetime.fromisoformat(utc_iso.replace("Z", "+00:00"))
    local = dt.astimezone().replace(tzinfo=None)
    return local.strftime("%Y-%m-%d %H:%M")

  # changed
def _build_tool_id_map(messages):
    """Build tool id map exactly like parse/search command flows."""
    tool_id_map = {}
    for msg in messages:
        for tool in msg.tools:
            if tool.get("type") == "tool_use" and "id" in tool:
                tool_id_map[tool["id"]] = tool.get("name", "Unknown")
    return tool_id_map


