        }
    }
}

/// Special parse output modes.
#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
pub enum ParseOutputMode {
    #[default]
    Full,
    OnlyMetadata,
    OnlyId,
}

impl ParseOutputMode {
    pub fn as_str(self) -> &'static str {
