    pub show_tools: ToolVisibility,
    pub show_agents: bool,
    pub show_custom: bool,
    pub show_branches: bool,
    pub show_plans: bool,
    pub allow_empty_output: bool,
    pub shorten: bool,
    pub shorten_max_chars: i64,
    pub shorten_progressive: bool,
    pub shorten_thinking: bool,
    pub color: bool,
