            let closing = characters[position + 1..]
                .iter()
                .position(|candidate| *candidate == character)
                .map(|offset| offset + position + 1)?;
            tokens.push(Token {
                kind: Kind::Term,
                text: characters[position + 1..closing].iter().collect(),
            });
            position = closing + 1;
            continue;
