                py,
                &line,
                line_facets,
                json_decode_error,
                &mut latest_title,
                &mut summaries,
            )?;
            line.clear();

            cursor = delimiter + 1;
            if block[delimiter] != b'\r' {
                continue;
            }
            if cursor == read_size {
                skip_leading_line_feed = true;
                continue;
            }
            if block[cursor] == b'\n' {
                cursor += 1;
            }
        }
    }

    if !line.is_empty() {
        accumulate_resolution_line(
            py,
            &line,
            line_facets,
            json_decode_error,
            &mut latest_title,
            &mut summaries,
        )?;
    }
