/// empty either way, so a caller cannot flush the same batch twice.
fn flush<S: HitSink>(
    pending: &mut Vec<PathBuf>,
    sink: &mut S,
    probe: &mut impl FnMut(&[PathBuf]) -> Vec<bool>,
    confirm: &mut impl FnMut(&Path) -> Confirmed,
