use num_bigint::BigInt;
use serde_json::{Map, Number, Value};
use unicode_general_category::{GeneralCategory, get_general_category};

pub const MESSAGE_KEYS: &[&str] = &[
    "type",
    "role",
    "original_index",
    "content",
    "branch",
    "isMeta",
    "sourceToolUserId",
    "agent_id",
    "subagent_type",
